#include <iostream>
using namespace std;

int main() {
    long long num;
    cin >> num;

    if (num <= 0 || num > 1000000000LL)
        return 0;

    int count = 0;

    for (int mask = 1; mask < (1 << 10); ++mask) {
        int bits = mask;
        long long value = 0;
        long long place = 1;

        while (bits > 0) {
            value += (bits & 1) * place;
            place *= 10;
            bits >>= 1;
        }

        if (value <= num)
            ++count;
    }

    cout << count;
    return 0;
}

